#ifndef SORT_H
#define SORT_H

typedef struct {
    long comparisons;
    long swaps;
} SortStats;

void print_array(const int a[], int n);
void bubble_sort(int a[], int n, SortStats *stats);
void insertion_sort(int a[], int n, SortStats *stats);

#endif

#include <stdio.h>
#include "sort.h"

void print_array(const int a[], int n) {
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

void bubble_sort(int a[], int n, SortStats *stats) {
    for (int pass = 0; pass < n - 1; pass++) {
        int swapped = 0;
        for (int j = 0; j < n - 1 - pass; j++) {
            stats->comparisons++;
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                stats->swaps++;
                swapped = 1;
            }
        }
        if (!swapped)
            break;
    }
}

void insertion_sort(int a[], int n, SortStats *stats) {
    for (int i = 1; i < n; i++) {
        int key = a[i];
        int j = i - 1;
        while (j >= 0) {
            stats->comparisons++;
            if (a[j] <= key)
                break;
            a[j + 1] = a[j];
            stats->swaps++;
            j--;
        }
        a[j + 1] = key;
    }
}

#ifndef REPORT_H
#define REPORT_H

#include "sort.h"

void print_stats(const char *name, SortStats s);

#endif

