#include <stdio.h>
#include "report.h"

void print_stats(const char *name, SortStats s) {
    printf("%-9s comparisons=%ld swaps=%ld\n", name, s.comparisons, s.swaps);
}

#include <stdio.h>
#include "sort.h"
#include "report.h"

int main(void) {
    int a[] = {5, 2, 9, 1, 6, 3};
    int b[] = {5, 2, 9, 1, 6, 3};
    SortStats sa = {0, 0}, sb = {0, 0};

    bubble_sort(a, 6, &sa);
    insertion_sort(b, 6, &sb);

    print_array(a, 6);
    print_stats("Bubble", sa);
    print_stats("Insertion", sb);
    return 0;
}
